import numpy as np, collections
np.set_printoptions(linewidth=220)
c1=np.load('cls1.npy'); c2=np.load('cls2.npy'); c3=np.load('cls3.npy'); c4=np.load('cls4.npy'); c5=np.load('cls5.npy')
def u32(a,i): return a[:,i:i+4].copy().view('<u4').ravel().astype(np.uint64)
def u16(a,i): return a[:,i:i+2].copy().view('<u2').ravel().astype(np.int64)

def show(v,label,n=12):
    u,c=np.unique(v,return_counts=True)
    o=np.argsort(c)[::-1][:n]
    print(f'{label}: uniq={len(u)} min={v.min()} max={v.max()} nullFF={int((v==0xffffffff).sum())} zero={int((v==0).sum())}')
    print('   top:', ' '.join(f'{int(u[i])}x{int(c[i])}' for i in o))

for name,a in [('1',c1),('2',c2),('3',c3)]:
    print('########## class',name, a.shape[0])
    for i in (34,38,63,67):
        show(u32(a,i),f'u32@{i}')
    for i in range(42,60,2):
        show(u16(a,i),f'u16@{i}')
    for i in (60,61,62):
        show(a[:,i].astype(np.int64),f'u8@{i}')
EOF
py -V:3.12 -I -B stats2.py

cd "D:/tmp2b/fm24-db/scratch/t05/people" && cat > slots.py <<'EOF'
import numpy as np, json, collections
np.set_printoptions(linewidth=240)
c = {k: np.load(f'cls{k}.npy') for k in (1,2,3,4,5)}

def u32(a,i): return a[:,i:i+4].copy().view('<u4').ravel().astype(np.int64)
def i16(a,i): return a[:,i:i+2].copy().view('<i2').ravel().astype(np.int64)
def u16(a,i): return a[:,i:i+2].copy().view('<u2').ravel().astype(np.int64)

def rep(v, label, n=8):
    u,cnt = np.unique(v, return_counts=True)
    o = np.argsort(cnt)[::-1][:n]
    print(f'{label:10s} uniq={len(u):7d} min={v.min():12d} max={v.max():12d} '
          f'neg={(v<0).sum():7d} zero={(v==0).sum():7d} | '
          + ' '.join(f'{int(u[i])}x{int(cnt[i])}' for i in o))

for k in (2,3):
    a = c[k]
    print(f'######## class {k}  n={a.shape[0]}')
    for i in (2,6,10,14,18,22,26,30,34):
        rep(u32(a,i), f'+{i} u32')
    eq = (a[:,10:14] == a[:,14:18]).all(axis=1)
    print('  +10dw==+14dw:', int(eq.sum()), '/', len(a))
    for i in (34,36,38,40,42,44,46,48,50,52,54,56,58):
        rep(u16(a,i), f'+{i} u16')
    for i in (50,52,54,56,58):
        rep(i16(a,i), f'+{i} i16')
    for i in (60,61,62,63):
        rep(a[:,i].astype(np.int64), f'+{i} u8')
    rep(u32(a,63), '+63 u32')
EOF
py -V:3.12 -I -B slots.py

