"""Global 4CC getter census for person POSITION + ATTRIBUTE codes (negative-result evidence)."""
import struct, json, collections
import capstone, pefile
EXE=r'D:\tmp2b\fm24\input\editor.exe'
raw=open(EXE,'rb').read()
pe=pefile.PE(EXE,fast_load=True)
secs=[(s.Name.rstrip(b'\x00').decode('latin1'),s.VirtualAddress,s.PointerToRawData,s.SizeOfRawData) for s in pe.sections]
BASE=pe.OPTIONAL_HEADER.ImageBase
def off2va(o):
    for n,va,pr,rs in secs:
        if pr<=o<pr+rs: return BASE+va+(o-pr)
def va2off(v):
    rva=v-BASE
    for n,va,pr,rs in secs:
        if va<=rva<va+rs: return pr+(rva-va)
md=capstone.Cs(capstone.CS_ARCH_X86,capstone.CS_MODE_64); md.detail=True
REG={capstone.x86.X86_REG_RDI:'rdi',capstone.x86.X86_REG_RBX:'rbx',capstone.x86.X86_REG_RSI:'rsi',capstone.x86.X86_REG_RCX:'rcx'}
SZ={1:'u8',2:'u16',4:'u32',8:'u64'}
POS=['Pgoa','Pdcb','Pdce','Pdmc','Pdml','Pdmr','Pwbl','Pwbr','Pmcb','Pmce','Pmcl','Pmcm','Pmcr','Pamc','Paml','Pamr','Pacm','Pstc','Pswp','Plcp']
ATTR=['PTck','PPas','PFin','PHea','PDri','PTec','PLon','PShp','PMar','PTck'.lower(),'PSta','PJum','Pfri','PBal','PStr','PAgi','PAcc','PPac']
def scan(off,follow=1):
    chain=[]
    for _ in range(12):
        d=list(md.disasm(raw[off:off+16],off2va(off) or 0,count=1))
        if not d: break
        q=d[0]
        if q.mnemonic in ('cmp','test','ret'): break
        chain.append(f'{q.mnemonic} {q.op_str}')
        if q.mnemonic=='jmp' and q.operands and q.operands[0].type==capstone.x86.X86_OP_IMM and follow>0:
            t=va2off(q.operands[0].imm)
            if t is None: break
            off=t; follow-=1; continue
        for op in q.operands:
            if op.type==capstone.x86.X86_OP_MEM and op.mem.base in REG and op.mem.disp:
                return {'reg':REG[op.mem.base],'disp':op.mem.disp,'size':op.size,'mnem':q.mnemonic},chain
        off+=q.size
    return None,chain
wanted=set(POS)|set(ATTR)
found=collections.defaultdict(list)
i=0
while True:
    i=raw.find(b'\x81\xfa',i)
    if i<0: break
    imm=struct.unpack_from('<I',raw,i+2)[0]
    code=struct.pack('>I',imm).decode('latin1','replace')
    if code in wanted:
        nxt=list(md.disasm(raw[i+6:i+22],off2va(i+6) or 0,count=1))
        if nxt and nxt[0].mnemonic in ('je','jne'):
            b=nxt[0]; tgt=b.operands[0].imm if b.operands and b.operands[0].type==capstone.x86.X86_OP_IMM else None
            for tag,o in (('ft',i+6+b.size),('tg',(va2off(tgt) if tgt else None))):
                if o is None: continue
                m,ch=scan(o)
                if m: found[code].append((tag,hex(o),f"{m['reg']}+{hex(m['disp'])}",SZ.get(m['size']),m['mnem']))
    i+=1
print('=== POSITION codes found in getter dispatch ===')
for c in POS:
    print(f'  {c}: {found.get(c,[]) or "NOT DISPATCHED"}')
print('=== ATTR codes ===')
for c in ATTR:
    if found.get(c): print(f'  {c}: {found[c]}')
json.dump({k:v for k,v in found.items()},open('l3_pos.json','w'),indent=1)
EOF
